  [TestCase(false,false)][TestCase(true,false)][TestCase(false,true)] public async Task NormalControllerUsesV2ButLegacyPendingKeepsItsOriginalContract(bool legacy,bool missingProgress){
   var p=Claim();string run=(string)p["runId"],preview=(string)p["rewardPreviewId"];bool claimed=false;RunApiHttpRequest posted=null;int sharedAfterClaim=0,getsAfterClaim=0;
   var session=SupportInquiryTests.Session();var wire=new Wire();
   var path=Path.GetFullPath("../QA/OperatorInformation-20261019/ClaimOwnerArchiveFiles/"+Guid.NewGuid().ToString("N"));var crypto=new ConfirmedRunReceiptArchiveTests.Crypto();
   var journal=new EncryptedRunOperationJournal(new AndroidEncryptedRunFilePort(crypto,Path.Combine(path,"pending.enc")));
   if(legacy)Assert.That(await journal.PutAsync(PendingRunOperation.Claim(session.AccountId,RunRewardClaimRequest.Create(run,preview,"legacy-original-key"),new AppBuildSnapshot("legacy-test",1),DateTimeOffset.Parse("2026-10-22T00:00:00Z"))),Is.True);
   using var client=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),journal,()=>session,()=>1,()=>new AppBuildSnapshot("normal-v2-test",2));
   using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);state.BindRunRecovery(client);var archive=new ConfirmedRunReceiptArchive(crypto,Path.Combine(path,"archive"));state.BindRunReceiptArchive(archive);
   await state.RefreshAccountAsync();if(!missingProgress)await state.StoryArchive.RefreshAsync();
   wire.Override=request=>{
    if(claimed&&request.Method=="GET")getsAfterClaim++;
    if(claimed&&(request.EndpointPath=="/v1/account/state"||request.EndpointPath=="/v1/wallet/crystals"||request.EndpointPath=="/v1/growth/state"))sharedAfterClaim++;
    JObject reply;
    if(request.Method=="POST"){
     posted=request;p["commandId"]=request.Headers.Single(h=>h.Name=="Idempotency-Key").Value;claimed=true;reply=(JObject)p.DeepClone();
     if(legacy)foreach(var key in new[]{"version","accountId","commandId","transactionReceipt","nextAction","owners"})reply.Remove(key);
    }else if(request.EndpointPath.EndsWith("/lifecycle",StringComparison.Ordinal)){
     reply=(JObject)typeof(RunLifecycleTests).GetMethod("Data",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{claimed?"CLAIMED":"CLAIMABLE"});
     reply["runId"]=run;reply["startResponse"]["runId"]=run;reply["finish"]["rewardPreviewId"]=preview;reply["reward"]["rewardPreviewId"]=preview;
     if(claimed){reply["reward"]["claimId"]=p["rewardClaimId"];reply["reward"]["receipt"]=p["transactionReceipt"].DeepClone();reply["reward"]["receipt"]["serverClaimedAt"]=DateTimeOffset.Parse((string)p["serverClaimedAt"]).ToUnixTimeMilliseconds();}
    }else if(request.EndpointPath.Contains("/reward-preview/"))reply=new JObject{["runId"]=run,["rewardPreviewId"]=preview,["status"]="ACTIVE",["claimability"]="CLAIMABLE",["balanceVersion"]="1",["expiresAt"]="2026-12-01T00:00:00Z",["serverCalculatedAt"]="2026-10-22T00:00:00Z",["rewardLines"]=p["rewardLines"].DeepClone(),["claim"]=new JObject{["claimable"]=true,["rewardClaimId"]=null,["claimedAt"]=null}};
    else if(request.EndpointPath=="/v1/account/state")reply=JObject.Parse(wire.Account);
    else return Task.FromResult(RunApiHttpResponse.Success(503,"{}"));
    return Task.FromResult(RunApiHttpResponse.Success(200,reply.ToString()));
   };
   await state.ReadRunResultsAsync(run);Assert.That(state.CanClaimRunReward(run),Is.True,state.RunResultNotice);await state.ClaimRunRewardAsync(run);
   Assert.That(posted,Is.Not.Null);var header=posted.Headers.FirstOrDefault(h=>h.Name=="X-Run-Claim-Version");Assert.That(header?.Value,Is.EqualTo(legacy?null:RunCompleteClaimReceipt.Version));
   var saved=await archive.ReadAsync(session.AccountId,run);Assert.That(saved,Is.Not.Null,state.RunResultNotice);Assert.That(saved.ResponseVersion,Is.EqualTo(legacy?null:RunCompleteClaimReceipt.Version));Assert.That(saved.IdempotencyKey,Is.EqualTo((string)p["commandId"]));
   if(legacy)Assert.That(saved.IdempotencyKey,Is.EqualTo("legacy-original-key"));else {Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(state.Account.Items[0].Number("quantity"),Is.EqualTo(5));}
   if(!legacy){Assert.That(getsAfterClaim,Is.EqualTo(missingProgress?1:0),"Confirmed v2 response completes lifecycle without a followup GET");Assert.That(sharedAfterClaim,Is.Zero,"Sufficient v2 owners must not force shared GETs");Assert.That(Complete(state),Is.EqualTo(!missingProgress),"Completion requires all owners and durable receipt");if(missingProgress)Assert.That(state.RunResultNotice,Is.Not.Empty);}
   Assert.That(state.VerifiedRunReceipt,Is.Not.Null);Assert.That((await journal.ReadAsync(session.AccountId)).Count,Is.Zero);
  }
  [Test] public async Task MissingProgressDefinitionDoesNotBlockFinancialAndWalletOwners(){
   var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);
   await state.RefreshAccountAsync();await state.RefreshWalletAsync();var p=Claim();WalletSnapshot(p);p["owners"]["progress"]=StoryProgressObservationTests.Progress(2,4);
   int before=wire.Calls,notices=0;state.Changed+=()=>notices++;
   Assert.That(Consume(state,p),Is.False);Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(state.Account.Items[0].Number("quantity"),Is.EqualTo(5));Assert.That(state.Wallet.TotalBalance,Is.EqualTo(33));Assert.That(state.StoryArchive.State,Is.Null);Assert.That(notices,Is.EqualTo(1));Assert.That(wire.Calls,Is.EqualTo(before));
   Assert.That(Consume(state,p),Is.False);Assert.That(notices,Is.EqualTo(1),"Duplicate partial apply must not republish unchanged owners");
   await state.StoryArchive.RefreshAsync();Assert.That(Consume(state,p),Is.True);Assert.That(state.StoryArchive.State.Order,Is.EqualTo(2));Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));
  }
  static bool Complete(AccountScreenRuntime state){var property=typeof(AccountScreenRuntime).GetProperty("RunClaimApplicationComplete");Assert.That(property,Is.Not.Null,"Missing owner and durable storage completion boundary");return (bool)property.GetValue(state);}
  [TestCase(false)][TestCase(true)] public async Task ArchivedClaimRecoversOnlyMissingProgressAndKeepsAppliedFinancialState(bool fail){
   var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshAccountAsync();await state.RefreshWalletAsync();
   var p=Claim();WalletSnapshot(p);p["owners"]["progress"]=StoryProgressObservationTests.Progress(2,4);
   var archive=new ConfirmedRunReceiptArchive(new ConfirmedRunReceiptArchiveTests.Crypto(),Path.GetFullPath("../QA/OperatorInformation-20261019/ClaimOwnerArchiveFiles/"+Guid.NewGuid().ToString("N")));Assert.That(await archive.StoreAsync(Operation(p)),Is.True);state.BindRunReceiptArchive(archive);
   bool observedComplete=false;state.Changed+=()=>{if(Complete(state))observedComplete=true;};int reads=0;wire.Override=request=>{Assert.That(request.EndpointPath,Is.EqualTo("/v1/story-progress"));Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(state.Wallet.TotalBalance,Is.EqualTo(33));reads++;return Task.FromResult(fail?RunApiHttpResponse.NetworkError("offline"):RunApiHttpResponse.Success(200,StoryProgressObservationTests.Observation().ToString()));};
   Assert.That(await state.ConsumeArchivedRunClaimAsync((string)p["runId"]),Is.EqualTo(!fail));Assert.That(reads,Is.EqualTo(1));Assert.That(Complete(state),Is.EqualTo(!fail));Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(await archive.ReadAsync(session.AccountId,(string)p["runId"]),Is.Not.Null);
   if(!fail){Assert.That(observedComplete,Is.True,"Completion transition must notify subscribers");Assert.That(state.StoryArchive.State.Order,Is.EqualTo(2));Assert.That(await state.ConsumeArchivedRunClaimAsync((string)p["runId"]),Is.True);Assert.That(reads,Is.EqualTo(1));}
  }
  [Test] public async Task SupersededArchiveReadCannotApplyOrStartRecovery(){
   var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshAccountAsync();await state.RefreshWalletAsync();
   var p=Claim();WalletSnapshot(p);var archive=new ConfirmedRunReceiptArchive(new ConfirmedRunReceiptArchiveTests.Crypto(),Path.GetFullPath("../QA/OperatorInformation-20261019/ClaimOwnerArchiveFiles/"+Guid.NewGuid().ToString("N")));Assert.That(await archive.StoreAsync(Operation(p)),Is.True);state.BindRunReceiptArchive(archive);
   var gate=(System.Threading.SemaphoreSlim)typeof(ConfirmedRunReceiptArchive).GetField("Gate",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);await gate.WaitAsync();Task<bool> reading;
   int before=wire.Calls;try{reading=state.ConsumeArchivedRunClaimAsync((string)p["runId"]);state.BindRunReceiptArchive(archive);}finally{gate.Release();}
   Assert.That(await reading,Is.False);Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(123));Assert.That(state.Wallet.TotalBalance,Is.EqualTo(15));Assert.That(wire.Calls,Is.EqualTo(before));
  }
  [Test] public async Task LateClaimResponsePreservesNewRunAndOriginalPendingReceipt(){
   var p=Claim();string run=(string)p["runId"],preview=(string)p["rewardPreviewId"];var session=SupportInquiryTests.Session();var wire=new Wire();
   var path=Path.GetFullPath("../QA/OperatorInformation-20261019/ClaimOwnerArchiveFiles/"+Guid.NewGuid().ToString("N"));var journal=new EncryptedRunOperationJournal(new AndroidEncryptedRunFilePort(new ConfirmedRunReceiptArchiveTests.Crypto(),Path.Combine(path,"pending.enc")));
   using var client=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),journal,()=>session,()=>1,()=>new AppBuildSnapshot("late-claim-test",1));using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);state.BindRunRecovery(client);
   var entered=new TaskCompletionSource<bool>();var release=new TaskCompletionSource<RunApiHttpResponse>();
   wire.Override=request=>{
    if(request.Method=="POST"){p["commandId"]=request.Headers.Single(h=>h.Name=="Idempotency-Key").Value;entered.TrySetResult(true);return release.Task;}
    JObject reply;if(request.EndpointPath.EndsWith("/lifecycle",StringComparison.Ordinal)){
     bool other=request.EndpointPath.Contains("run_other");string id=other?"run_other":run;
     reply=(JObject)typeof(RunLifecycleTests).GetMethod("Data",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{other?"CLAIMED":"CLAIMABLE"});reply["runId"]=id;reply["startResponse"]["runId"]=id;reply["finish"]["rewardPreviewId"]=preview;reply["reward"]["rewardPreviewId"]=preview;
     if(other){reply["reward"]["claimId"]=p["rewardClaimId"];reply["reward"]["receipt"]=p["transactionReceipt"].DeepClone();reply["reward"]["receipt"]["runId"]=id;reply["reward"]["receipt"]["serverClaimedAt"]=DateTimeOffset.Parse((string)p["serverClaimedAt"]).ToUnixTimeMilliseconds();}
    }else reply=new JObject{["runId"]=run,["rewardPreviewId"]=preview,["status"]="ACTIVE",["claimability"]="CLAIMABLE",["balanceVersion"]="1",["expiresAt"]="2026-12-01T00:00:00Z",["serverCalculatedAt"]="2026-10-22T00:00:00Z",["rewardLines"]=p["rewardLines"].DeepClone(),["claim"]=new JObject{["claimable"]=true,["rewardClaimId"]=null,["claimedAt"]=null}};
    return Task.FromResult(RunApiHttpResponse.Success(200,reply.ToString()));
   };
   await state.ReadRunResultsAsync(run);Assert.That(state.CanClaimRunReward(run),Is.True,state.RunResultNotice);var claiming=state.ClaimRunRewardAsync(run);Assert.That(await Task.WhenAny(entered.Task,Task.Delay(3000)),Is.SameAs(entered.Task),"Claim POST not reached");var otherReading=state.ReadRunResultsAsync("run_other");int before=wire.Calls;
   release.SetResult(RunApiHttpResponse.Success(200,p.ToString()));await Task.WhenAll(claiming,otherReading);
   Assert.That(state.Lifecycle.RunId,Is.EqualTo("run_other"));Assert.That(wire.Calls,Is.EqualTo(before+1),"Only the newly requested run lifecycle is read");var pending=(await journal.ReadAsync(session.AccountId)).Single();Assert.That(pending.TargetId,Is.EqualTo(run));Assert.That(pending.AcceptedResponseJson,Is.Not.Null);
  }
  [Test] public void SameVersionFinancialReadWithDefaultZeroProjectionMatchesSparseReceipt(){
   var p=Claim();var json=JObject.Parse(AccountStateReadTests.Json());json["mutationSequence"]=7;json["currencies"]=new JObject{["CREDITS"]=110,["MACHINE_PARTS"]=0,["TACTICAL_DATA"]=0,["SPECIAL_CORE"]=0,["OPERATOR_EXP"]=0};json["items"]=p["owners"]["account"]["items"].DeepClone();
   var current=AccountStateSnapshot.Parse(json.ToString(),"account_test");Assert.That(Apply(current,p,out var next),Is.True);Assert.That(next,Is.SameAs(current));
   json["currencies"]["MACHINE_PARTS"]=1;Assert.That(Apply(AccountStateSnapshot.Parse(json.ToString(),"account_test"),p,out _),Is.False,"Nonzero omitted currency conflicts");
   json["currencies"]["MACHINE_PARTS"]=0;json["currencies"]["UNKNOWN"]=0;Assert.That(Apply(AccountStateSnapshot.Parse(json.ToString(),"account_test"),p,out _),Is.False,"Unknown omission is not a known projection default");
  }
  static JObject Claim(long sequence=7,long credits=110){var p=(JObject)GameApiJson.ReadObject(File.ReadAllText(Path.GetFullPath("../QA/CommanderS1-20260922/run-complete-claim-example-20261019.json")))["response"];p["accountId"]="account_test";p["commandId"]="owner-claim-original-key";p["owners"]["account"]["beforeMutationSequence"]=sequence-1;p["owners"]["account"]["mutationSequence"]=sequence;p["owners"]["account"]["currencies"][0]["balance"]=credits;return p;}
  static RunCompleteClaimReceipt Receipt(JObject p)=>RunCompleteClaimReceipt.Read(p.ToString(),(string)p["accountId"],(string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]);
  static bool Apply(AccountStateSnapshot state,JObject claim,out AccountStateSnapshot next){var method=typeof(AccountStateSnapshot).GetMethod("TryApplyRunClaimFinancial",BindingFlags.Instance|BindingFlags.NonPublic);Assert.That(method,Is.Not.Null,"Missing financial owner consumption");var args=new object[]{Receipt(claim),null};bool accepted=(bool)method.Invoke(state,args);next=(AccountStateSnapshot)args[1];return accepted;}
  static long Version(AccountStateSnapshot state)=>(long)typeof(AccountStateSnapshot).GetProperty("FinancialMutationSequence").GetValue(state);
  static PendingRunOperation Operation(JObject p)=>PendingRunOperation.CompleteClaim((string)p["accountId"],RunRewardClaimRequest.Create((string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]),new AppBuildSnapshot("owner-test",1),DateTimeOffset.Parse("2026-10-22T00:00:00Z")).Confirmed(p.ToString());
  static bool Consume(AccountScreenRuntime state,JObject p){var method=typeof(AccountScreenRuntime).GetMethod("TryApplyCompleteRunClaim",BindingFlags.Instance|BindingFlags.NonPublic);Assert.That(method,Is.Not.Null,"Missing actual claim owner coordinator");return (bool)method.Invoke(state,new object[]{Operation(p)});}
  sealed class Wire:IRunApiHttpTransport {public int Calls;public long? WalletVersion;public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Override;public string Account=AccountStateReadTests.Json();public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest request){Calls++;if(Override!=null)return Override(request);var wallet=JObject.Parse("{\"currencyId\":\"cur_crystal\",\"policyVersion\":\"fixture\",\"freeBalance\":12,\"paidBalance\":3,\"totalBalance\":15,\"spendOrder\":[\"FREE\",\"PAID\"],\"ticketExchange\":null,\"purchaseConfigured\":false}");if(WalletVersion.HasValue)wallet["stateVersion"]=new JObject{["version"]="crystal-wallet.snapshot.v1.20261022",["accountId"]="account_test",["mutationSequence"]=WalletVersion.Value,["coverage"]=new JArray("BALANCES")};return Task.FromResult(RunApiHttpResponse.Success(200,request.EndpointPath=="/v1/account/state"?Account:request.EndpointPath=="/v1/story-progress"?StoryProgressObservationTests.Observation().ToString():wallet.ToString()));}}
  static void WalletSnapshot(JObject p,string policy="fixture"){long seq=(long)p["owners"]["account"]["mutationSequence"];p["owners"]["wallet"]=new JObject{["kind"]="SNAPSHOT",["coverage"]=new JArray("BALANCES"),["currencyId"]="cur_crystal",["policyVersion"]=policy,["freeBalance"]=30,["paidBalance"]=3,["totalBalance"]=33,["sourceMutation"]=new JObject{["versionSource"]="CRYSTAL_OPERATION_MUTATION",["operationId"]="wallet_fixture",["basisAccountSequence"]=seq-1,["mutationSequence"]=seq}};}
  [Test] public async Task AllOwnersAreCommittedBeforeNotificationAndOldReadCannotRollBack(){var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshAccountAsync();await state.RefreshWalletAsync();await state.StoryArchive.RefreshAsync();var p=Claim();WalletSnapshot(p);int before=wire.Calls,notices=0;state.Changed+=()=>{notices++;Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(state.Wallet.TotalBalance,Is.EqualTo(33));var value=state.StoryArchive.GetType().GetProperty("ConfirmedProgress").GetValue(state.StoryArchive);Assert.That(value,Is.Not.Null);};Assert.That(Consume(state,p),Is.True);Assert.That(notices,Is.EqualTo(1));Assert.That(wire.Calls,Is.EqualTo(before));Assert.That(state.Wallet.PolicyVersion,Is.EqualTo("fixture"));Assert.That(state.Wallet.PurchaseConfigured,Is.False);await state.RefreshWalletAsync();Assert.That(state.Wallet.TotalBalance,Is.EqualTo(33));await state.RefreshAccountAsync();Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));}
  [Test] public async Task NonemptyProgressAndWalletAreAppliedTogetherAndArchiveRestoresFreshOwners(){var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshAccountAsync();await state.RefreshWalletAsync();await state.StoryArchive.RefreshAsync();var p=Claim();WalletSnapshot(p);p["owners"]["progress"]=StoryProgressObservationTests.Progress(2,4);int before=wire.Calls,notices=0;state.Changed+=()=>{notices++;Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(state.Wallet.TotalBalance,Is.EqualTo(33));Assert.That(state.StoryArchive.State.Order,Is.EqualTo(2));Assert.That(state.StoryArchive.State.UnlockedOperations,Does.Contain("opn_03_water_stop"));};Assert.That(Consume(state,p),Is.True);Assert.That(notices,Is.EqualTo(1));Assert.That(wire.Calls,Is.EqualTo(before));
   var path=Path.GetFullPath("../QA/OperatorInformation-20261019/ClaimOwnerArchiveFiles/"+Guid.NewGuid().ToString("N"));Assert.That(await new ConfirmedRunReceiptArchive(new ConfirmedRunReceiptArchiveTests.Crypto(),path).StoreAsync(Operation(p)),Is.True);using var fresh=new AccountScreenRuntime(wire,null,()=>session,()=>1);await fresh.RefreshAccountAsync();await fresh.RefreshWalletAsync();await fresh.StoryArchive.RefreshAsync();fresh.BindRunReceiptArchive(new ConfirmedRunReceiptArchive(new ConfirmedRunReceiptArchiveTests.Crypto(),path));before=wire.Calls;Assert.That(await fresh.ConsumeArchivedRunClaimAsync((string)p["runId"]),Is.True);Assert.That(fresh.StoryArchive.State.Order,Is.EqualTo(2));Assert.That(fresh.Wallet.TotalBalance,Is.EqualTo(33));Assert.That(fresh.Account.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(wire.Calls,Is.EqualTo(before));}
