  [TestCase("account")][TestCase("coverage")][TestCase("version")][TestCase("sequence")] public async Task InvalidWalletObservationCannotBecomeReady(string fault){var wire=new Wire{WalletVersion=1};var body=JObject.Parse((await wire.SendAsync(new RunApiHttpRequest("GET","/v1/wallet/crystals",null,null))).BodyJson);if(fault=="account")body["stateVersion"]["accountId"]="other";if(fault=="coverage")body["stateVersion"]["coverage"]=new JArray("ALL");if(fault=="version")body["stateVersion"]["version"]="unknown";if(fault=="sequence")body["stateVersion"]["mutationSequence"]=-1;wire.Override=_=>Task.FromResult(RunApiHttpResponse.Success(200,body.ToString()));var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshWalletAsync();Assert.That(state.Wallet.Status,Is.EqualTo(CrystalWalletReadStatus.Invalid));}
  [Test] public async Task ConflictingSameVersionGetPreservesBalancesButInvalidatesReadiness(){var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshAccountAsync();await state.RefreshWalletAsync();await state.StoryArchive.RefreshAsync();var p=Claim();WalletSnapshot(p);Assert.That(Consume(state,p),Is.True);wire.WalletVersion=7;await state.RefreshWalletAsync();Assert.That(state.Wallet.TotalBalance,Is.EqualTo(33));Assert.That(state.Wallet.Status,Is.EqualTo(CrystalWalletReadStatus.Invalid));Assert.That(Consume(state,p),Is.False);}
  [TestCase(true)][TestCase(false)] public async Task FailedReadAndSameAccountCredentialRotationKeepVersionFences(bool wallet){var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshAccountAsync();await state.RefreshWalletAsync();await state.StoryArchive.RefreshAsync();var p=Claim();WalletSnapshot(p);Assert.That(Consume(state,p),Is.True);wire.Override=_=>Task.FromResult(RunApiHttpResponse.NetworkError("fixture"));if(wallet)await state.RefreshWalletAsync();else await state.RefreshAccountAsync();session=SupportInquiryTests.Session();state.SynchronizeSession();wire.Override=null;if(wallet){await state.RefreshWalletAsync();Assert.That(state.Wallet.TotalBalance,Is.EqualTo(33));}else {await state.RefreshAccountAsync();Assert.That(state.Account.Currencies["CREDITS"],Is.EqualTo(110));}}
  [Test] public async Task CredentialRotationDuringWalletRefreshRequiresReplacementRead(){var wire=new Wire{WalletVersion=1};var session=SupportInquiryTests.Session();using var state=new AccountScreenRuntime(wire,null,()=>session,()=>1);await state.RefreshWalletAsync();var gate=new TaskCompletionSource<RunApiHttpResponse>();wire.Override=_=>gate.Task;var interrupted=state.RefreshWalletAsync();try{session=SupportInquiryTests.Session();state.SynchronizeSession();wire.Override=null;int before=wire.Calls;await state.EnsureWalletAsync();Assert.That(wire.Calls,Is.EqualTo(before+1),"Interrupted explicit refresh must not be mistaken for completed readiness");Assert.That(state.Wallet.TotalBalance,Is.EqualTo(15));Assert.That(state.Wallet.Status,Is.EqualTo(CrystalWalletReadStatus.Ready));}finally{gate.TrySetResult(RunApiHttpResponse.NetworkError("old"));await interrupted;}}
  [Test] public void FinancialSnapshotAppliesAcrossGapWithoutPromotingUnrelatedState(){var before=AccountStateSnapshot.Parse(AccountStateReadTests.Json(),"account_test");Assert.That(Apply(before,Claim(),out var after),Is.True);Assert.That(after.Currencies["CREDITS"],Is.EqualTo(110));Assert.That(after.Items[0].Text("itemId"),Is.EqualTo("item-fixture"));Assert.That(after.Items[0].Number("quantity"),Is.EqualTo(5));Assert.That(after.Operators,Is.SameAs(before.Operators));Assert.That(after.Presets,Is.SameAs(before.Presets));Assert.That(after.MutationSequence,Is.EqualTo(before.MutationSequence));Assert.That(Version(after),Is.EqualTo(7));Assert.That(before.Currencies["CREDITS"],Is.EqualTo(123));}
  [Test] public void OlderAndDuplicateClaimsNeverAddOrRollBack(){var first=AccountStateSnapshot.Parse(AccountStateReadTests.Json(),"account_test");Assert.That(Apply(first,Claim(9,999),out var latest),Is.True);Assert.That(Apply(latest,Claim(7,110),out var old),Is.True);Assert.That(old,Is.SameAs(latest));Assert.That(Apply(latest,Claim(9,999),out var duplicate),Is.True);Assert.That(duplicate,Is.SameAs(latest));Assert.That(Apply(latest,Claim(9,111),out _),Is.False);}
  [Test] public void NullFuelDoesNotEraseKnownFuelAndUncoveredCurrencyIsNotInvented(){var before=AccountStateSnapshot.Parse(AccountStateReadTests.Json(),"account_test");var p=Claim();p["owners"]["account"]["fuel"]=JValue.CreateNull();Assert.That(Apply(before,p,out var after),Is.True);Assert.That(after.Fuel,Is.SameAs(before.Fuel));Assert.That(after.Currencies.ContainsKey("MACHINE_PARTS"),Is.False);}
  [Test] public void ReceiptFromDifferentAccountIsRejected(){var before=AccountStateSnapshot.Parse(AccountStateReadTests.Json(),"account_test");var p=Claim();p["accountId"]="other_account";Assert.That(Apply(before,p,out _),Is.False);}
